from pathlib import Path

path = Path('/home/ubuntu/swapphone/client/src/App.tsx')
app = path.read_text()
start = app.index('<section className="container py-10 md:py-16">')
end = app.index('<section className="bg-[#efeee9] py-20 md:py-28">', start)
replacement = '''<section className="container py-10 md:py-16"><div className="flex items-end justify-between"><div><p className="eyebrow">Browse devices</p><h2 className="font-display mt-3 text-3xl font-medium tracking-[-.055em] md:text-5xl">Latest iPhone models.</h2><p className="mt-3 max-w-md text-sm leading-6 text-[#707773]">See the models people are looking for, with checked devices and clear prices.</p></div><Link href="/browse?q=iPhone" className="hidden text-xs font-medium underline decoration-[#a6b89a] underline-offset-4 md:block">See all iPhones <ArrowRight size={13} className="ml-1 inline"/></Link></div><div className="no-scrollbar mt-7 flex snap-x gap-4 overflow-x-auto pb-3 md:grid md:grid-cols-4 md:overflow-visible">{catalog.models.filter((model) => model.brandId === 'apple').slice(0, 4).map((model) => { const listings = catalog.products.filter((product) => product.modelId === model.id); const first = listings[0]; return <button key={model.id} onClick={() => setLocation(`/browse?q=${encodeURIComponent(model.name)}`)} className="group min-w-[250px] snap-start overflow-hidden rounded-[1.6rem] border border-[#e3e3dc] bg-white text-left md:min-w-0"><div className="h-[220px] bg-[#f0efeb] bg-cover bg-center transition duration-500 group-hover:scale-[1.03]" style={{ backgroundImage: `url(${first?.images.primary || '/manus-storage/swapphone-hero_c76449fc.png'})` }}/><div className="border-t border-[#e3e3dc] p-4"><div className="flex items-center justify-between gap-3"><p className="font-display text-lg tracking-[-.035em]">{model.name.replace('iPhone ', 'iPhone ')}</p><span className="h-2.5 w-2.5 rounded-full bg-[#9aa99a]"/></div><p className="mt-1 text-xs text-[#7b837e]">{listings.length} checked {listings.length === 1 ? 'phone' : 'phones'}</p><p className="mt-4 text-[11px] font-semibold uppercase tracking-[.14em] text-[#60735b]">From {first ? money(first.pricing.price) : 'See price'} <ArrowRight size={13} className="ml-1 inline transition group-hover:translate-x-1"/></p></div></button>; })}</div></section>'''
path.write_text(app[:start] + replacement + app[end:])
